CREATE OR REPLACE FUNCTION essay_private.credit_post_grant(p_user uuid, p_quantity integer, p_origin text, p_key text, p_reason text, p_actor text, p_expires timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare account uuid; g public.credit_grants; t public.credit_transactions;
begin
 if p_user is null or p_quantity is null or p_quantity<=0 or p_quantity>100000
 or p_origin is null or p_origin not in ('purchase','signup_bonus','promotion','admin_grant','compensation','b2b_program')
 or nullif(btrim(p_key),'') is null or length(p_key)>200 or nullif(btrim(p_reason),'') is null or nullif(btrim(p_actor),'') is null
 or not exists(select 1 from public.profiles where id=p_user) then raise sqlstate 'PT422' using message='INVALID_GRANT';end if;
 perform account_private.lock_subject(p_user);
 if not account_private.allowed(p_user) then raise insufficient_privilege using message='ACCOUNT_RESTRICTED';end if;
 insert into public.credit_accounts(user_id) values(p_user) on conflict(user_id) do nothing;
 select id into account from public.credit_accounts where user_id=p_user for update;
 select * into g from public.credit_grants where external_reference=p_key;
 if g.id is not null then
  select * into t from public.credit_transactions where idempotency_key='grant/'||p_key;
  if g.account_id is distinct from account or g.origin is distinct from p_origin or g.expires_at is distinct from p_expires
  or t.balance_delta is distinct from p_quantity or t.reason_code is distinct from p_reason or t.actor_reference is distinct from p_actor
  then raise sqlstate 'PT409' using message='CONFLICT';end if;return g.id;
 end if;
 if p_expires is not null and p_expires<=essay_private.clock() then raise sqlstate 'PT422' using message='INVALID_EXPIRY';end if;
 insert into public.credit_grants(account_id,origin,external_reference,expires_at) values(account,p_origin,p_key,p_expires) returning * into g;
 insert into public.credit_transactions(account_id,grant_id,transaction_type,balance_delta,reserved_delta,idempotency_key,reason_code,actor_reference)
 values(account,g.id,p_origin,p_quantity,0,'grant/'||p_key,p_reason,p_actor);
 return g.id;
exception when unique_violation then raise sqlstate 'PT409' using message='CONFLICT';
end$function$

CREATE OR REPLACE FUNCTION public.account_benefit_claim(p_subject uuid, p_markers jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare m jsonb;known boolean=false;g uuid;begin
 perform account_private.lock_subject(p_subject);
 if not account_private.allowed(p_subject) or not exists(select 1 from auth.users where id=p_subject) then raise insufficient_privilege;end if;
 if jsonb_typeof(p_markers) is distinct from 'array' or jsonb_array_length(p_markers) not between 1 and 16 then raise invalid_parameter_value;end if;
 for m in select value from jsonb_array_elements(p_markers) order by value->>'version',value->>'marker' loop
 if m-array['version','marker']<>'{}' or m->>'version' !~ '^[a-zA-Z0-9_-]{1,32}$' or m->>'marker' !~ '^[a-f0-9]{64}$' or not(m ?& array['version','marker']) then raise invalid_parameter_value;end if;
 perform pg_advisory_xact_lock(hashtextextended(m->>'version'||'/'||(m->>'marker'),91571));
 known=known or exists(select 1 from account_private.benefit_claims where benefit_type='essay_signup_3_v1' and key_version=m->>'version' and marker=m->>'marker');
 end loop;
 select grant_id into g from account_private.benefit_delivery where subject_id=p_subject;
 -- Existing live-account grant seeds coverage; never re-grant on migration.
 if g is null then select cg.id into g from public.credit_grants cg join public.credit_accounts ca on ca.id=cg.account_id where ca.user_id=p_subject and cg.origin='signup_bonus';end if;
 if not known and g is null then
 if not essay_private.credit_signup_eligible(p_subject) then return jsonb_build_object('state','NOT_ELIGIBLE');end if;
 g=essay_private.credit_post_grant(p_subject,3,'signup_bonus','signup/'||gen_random_uuid()::text,'signup_bonus_v1','system/signup_bonus',null);
 end if;
 for m in select value from jsonb_array_elements(p_markers) loop
 insert into account_private.benefit_claims(benefit_type,key_version,marker) values('essay_signup_3_v1',m->>'version',m->>'marker') on conflict do nothing;
 end loop;
 insert into account_private.benefit_delivery values(p_subject,g) on conflict(subject_id) do nothing;
 return jsonb_build_object('state',case when g is null then 'PREVIOUSLY_CLAIMED' else 'GRANTED' end);
end$function$
